            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.DAMAGE_TYPE, (int)damageType);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.GUARD, guard);
            m_pEventSystem.EVENTVAR_SetMulValue(EventVar.Label.RATIO, 0x1000, 0x19a, 0x20000);
            m_pEventSystem.CallEvent(EventID.DEFENDER_GUARD);
            guard = (ushort)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GUARD);
            int ratio = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO);
            m_pEventSystem.EVENTVAR_Pop();

            return (ushort)calc.MulRatio(guard, ratio);
        }
		public int Event_CalcTypeMatchRatio(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, byte waza_type) {
            bool isMatch = attacker.IsMatchType(waza_type);

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.GEN_FLAG, isMatch ? TRUE : FALSE);
            m_pEventSystem.CallEvent(EventID.TYPEMATCH_CHECK);
            int matchFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GEN_FLAG);
            int ratio = matchFlag != FALSE ? 0x1800 : 0x1000;
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.TYPEMATCH_FLAG, matchFlag != FALSE ? TRUE : FALSE);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.RATIO, ratio);
            m_pEventSystem.CallEvent(EventID.TYPEMATCH_RATIO);
            ratio = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO);
            m_pEventSystem.EVENTVAR_Pop();

            return ratio;
        }
		public global::Pml.Battle.TypeAffinity.AffinityID Event_CheckDamageAffinity(in global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, in global::Dpr.Battle.Logic.BTL_POKEPARAM defender, byte wazaType, bool onlyAttacker) {
            if (wazaType == (byte)PokeType.NULL)
                return TypeAffinity.AffinityID.TYPEAFF_1;

            PokeTypePair pair = defender.GetPokeType();

            byte type1 = PokeTypePair.GetType1(pair);
            TypeAffinity.AffinityID aff = Event_CheckDamageAffinity(attacker, defender, wazaType, type1, onlyAttacker);

            if (PokeTypePair.IsPure(pair, true))
                return aff;

            byte type2 = PokeTypePair.GetType2(pair);
            if (type2 != (byte)PokeType.NULL && type2 != type1)
                aff = calc.TypeAffMul(aff, Event_CheckDamageAffinity(attacker, defender, wazaType, type2, onlyAttacker));

            byte typeEx = PokeTypePair.GetTypeEx(pair);
            if (typeEx != type2 && typeEx != (byte)PokeType.NULL && typeEx != type1)
                return calc.TypeAffMul(aff, Event_CheckDamageAffinity(attacker, defender, wazaType, typeEx, onlyAttacker));

            return aff;
        }
		public global::Pml.Battle.TypeAffinity.AffinityID Event_CheckDamageAffinity(in global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, in global::Dpr.Battle.Logic.BTL_POKEPARAM defender, byte waza_type, byte defenderType, bool onlyAttacker) {
            EventID eventID = onlyAttacker ? EventID.CHECK_AFFINITY_ONLY_ATTACKER : EventID.CHECK_AFFINITY;

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, defender.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKE_TYPE, defenderType);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZA_TYPE, waza_type);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FLAT_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FLATMASTER_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.TYPEAFF, (int)TypeAffinity.AffinityID.TYPEAFF_NULL);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.WAZA_TYPE_EX, (int)PokeType.NULL);

            if (defender.CheckSick(WazaSick.WAZASICK_MIYABURU))
            {
                BTL_SICKCONT sickCont = defender.GetSickCont(WazaSick.WAZASICK_MIYABURU);
                byte flatType = (byte)SICKCONT.GetParam(sickCont);
                if ((byte)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.POKE_TYPE) == flatType)
                {
                    EventVar.Label label = SICKCONT.GetFlag(sickCont) ? EventVar.Label.FLATMASTER_FLAG : EventVar.Label.FLAT_FLAG;
                    m_pEventSystem.EVENTVAR_RewriteValue(label, TRUE);
                }
            }

            if (defender.CheckSick(WazaSick.WAZASICK_NEWOHARU) && m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.WAZA_TYPE) == (int)PokeType.JIMEN)
                m_pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.FLAT_FLAG, TRUE);

            if (defender.CheckSick(WazaSick.WAZASICK_FLYING_CANCEL) && m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.WAZA_TYPE) == (int)PokeType.JIMEN)
                m_pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.FLAT_FLAG, TRUE);

            m_pEventSystem.CallEvent(eventID);

            int flatFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FLAT_FLAG);
            int flatMasterFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FLATMASTER_FLAG);
            byte wazaTypeEx = (byte)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.WAZA_TYPE_EX);
            TypeAffinity.AffinityID aff = (TypeAffinity.AffinityID)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.TYPEAFF);

            m_pEventSystem.EVENTVAR_Pop();

            if (flatMasterFlag != FALSE)
                return TypeAffinity.AffinityID.TYPEAFF_1;

            if (aff == TypeAffinity.AffinityID.TYPEAFF_NULL)
                aff = calc.TypeAff((PokeType)waza_type, (PokeType)defenderType);

            if (wazaTypeEx != (byte)PokeType.NULL)
                aff = calc.TypeAffMul(aff, calc.TypeAff((PokeType)wazaTypeEx, (PokeType)defenderType));

            if (aff == TypeAffinity.AffinityID.TYPEAFF_0 && flatFlag != FALSE)
                aff = TypeAffinity.AffinityID.TYPEAFF_1;

            return aff;
        }
		public global::Pml.Battle.TypeAffinity.AffinityID Event_RewriteWazaAffinity(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.BTL_POKEPARAM defender, byte wazaType, global::Pml.Battle.TypeAffinity.AffinityID affinity) {
            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, defender.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZA_TYPE, wazaType);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.TYPEAFF, (int)affinity);
            m_pEventSystem.CallEvent(EventID.REWRITE_AFFINITY);
            affinity = (TypeAffinity.AffinityID)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.TYPEAFF);
            m_pEventSystem.EVENTVAR_Pop();
            return affinity;
        }
		public bool Event_CheckFloating(global::Dpr.Battle.Logic.BTL_POKEPARAM poke, bool isIncludeHikouType) {
            bool isFloating = isIncludeHikouType && poke.IsMatchType((byte)PokeType.HIKOU);

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID, poke.GetID());
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.GEN_FLAG, isFloating ? TRUE : FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FAIL_FLAG, FALSE);
            m_pEventSystem.CallEvent(EventID.CHECK_FLYING);

            if (poke.CheckSick(WazaSick.WAZASICK_NEWOHARU))
                m_pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.FAIL_FLAG, TRUE);

            if (poke.CheckSick(WazaSick.WAZASICK_FLYING_CANCEL))
                m_pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.FAIL_FLAG, TRUE);

            if (poke.CheckSick(WazaSick.WAZASICK_TELEKINESIS) || poke.CheckSick(WazaSick.WAZASICK_FLYING))
                m_pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.GEN_FLAG, TRUE);

            int genFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GEN_FLAG);
            int failFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FAIL_FLAG);
            m_pEventSystem.EVENTVAR_Pop();

            return genFlag != FALSE && failFlag == FALSE;
        }
