		public uint Event_CalcKickBack(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Pml.WazaNo waza, uint inDamage, out bool isMustEnable) {
            byte pokeID = attacker.GetID();
            byte ratio = WAZADATA.GetDamageReactionRatio(waza);
            isMustEnable = false;

            // 1: ratio of the damage dealt, 2: ratio of the max HP, 0: none
            int reactionType;
            if (ratio != 0)
            {
                reactionType = 1;
            }
            else
            {
                ratio = WAZADATA.GetHPReactionRatio(waza);
                reactionType = ratio != 0 ? 2 : 0;
            }

            if (WAZADATA.GetCategory(waza) == WazaCategory.DRAIN)
                return 0;

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, pokeID);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.RATIO, ratio);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.RATIO_EX, 0);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FAIL_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.GEN_FLAG, FALSE);
            m_pEventSystem.CallEvent(EventID.CALC_KICKBACK);
            int newRatio = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO);
            int failFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FAIL_FLAG);
            int mustFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GEN_FLAG);
            bool isMust = mustFlag != FALSE;
            int ratioEx = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO_EX);
            m_pEventSystem.EVENTVAR_Pop();

            if (failFlag != FALSE && mustFlag == FALSE)
                return 0;

            byte totalRatio = (byte)(ratioEx + newRatio);
            if (totalRatio == 0)
                return 0;

            uint damage;
            if (reactionType == 2)
                inDamage = (uint)attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP_BEFORE_G);

            if (reactionType != 2 && inDamage == 0)
                damage = 0;
            else
                damage = (uint)calc.Roundup((int)calc.MulRatioInt(inDamage, totalRatio), 1);

            isMustEnable = isMust;
            return damage;
        }
