		public ushort Event_CalcAgility(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, bool fTrickRoomEnable) {
            int agility = attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_AGILITY);

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.AGILITY, agility);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.GEN_FLAG, TRUE);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.TRICK_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetMulValue(EventVar.Label.RATIO, 0x1000, 0x19a, 0x20000);
            m_pEventSystem.CallEvent(EventID.CALC_AGILITY);

            uint newAgility = (uint)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.AGILITY);
            int ratio = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO);
            uint result = calc.MulRatio(newAgility, ratio);

            if (attacker.GetPokeSick() == Sick.MAHI && m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GEN_FLAG) != FALSE)
                result = result * 50 / 100;

            if (result >= 10000)
                result = 10000;

            if (fTrickRoomEnable && m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.TRICK_FLAG) != FALSE)
                result = 10000 - result;

            m_pEventSystem.EVENTVAR_Pop();

            return (ushort)result;
        }
