		public bool Event_CheckHit(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.BTL_POKEPARAM defender, global::Dpr.Battle.Logic.WazaParam wazaParam, out bool bFriendshipActive) {
            bFriendshipActive = false;

            PosPoke posPoke = m_pBattleEnv.GetPosPoke();
            if (SectionUtil.CheckMustHit(m_pMainModule, attacker, defender, posPoke) ||
                m_pMainModule.GetCompetitor(false) == BtlCompetitor.BTL_COMPETITOR_DEMO_CAPTURE ||
                Event_IsCalcHitCancel(attacker, defender, wazaParam.wazaID) ||
                defender.CheckSick(WazaSick.WAZASICK_TELEKINESIS))
            {
                return true;
            }

            uint hitPer = Event_getHitPer(EventID.WAZA_HIT_RATIO, attacker, defender, wazaParam);

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, defender.GetID());
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FLAT_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.HIT_RANK, attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_HIT_RATIO));
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.AVOID_RANK, defender.GetValue(BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO));
            m_pEventSystem.EVENTVAR_SetMulValue(EventVar.Label.RATIO, 0x1000, 0x29, 0x20000);
            m_pEventSystem.CallEvent(EventID.WAZA_HIT_RANK);

            sbyte hitRank = (sbyte)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.HIT_RANK);
            sbyte avoidRank = (sbyte)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.AVOID_RANK);
            int flatFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FLAT_FLAG);

            bool isMiyaburuFlat = defender.CheckSick(WazaSick.WAZASICK_MIYABURU) && avoidRank > 6;

            if (attacker.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_HITRATIO_UP))
                m_pEventSystem.EVENTVAR_MulValue(EventVar.Label.RATIO, 0x1333);

            int ratio = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO);
            m_pEventSystem.EVENTVAR_Pop();

            if (isMiyaburuFlat || flatFlag != FALSE)
                avoidRank = 6;

            int rank = calc.RoundValue(hitRank - avoidRank + 6, 0, 12);
            uint per = calc.MulRatio(calc.HitPer((byte)hitPer, (byte)rank), ratio);
            if (per >= 100)
                per = 100;

            if (SectionUtil.GetFriendship(m_pMainModule, defender) == 255)
            {
                per = per > 10 ? per - 10 : 0;
                bFriendshipActive = true;
            }

            return perOccur((byte)per, out _);
        }
