		public global::Dpr.Battle.Logic.KoraeruCause Event_CheckKoraeru(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.BTL_POKEPARAM defender, bool isWazaDamage, ref ushort damage) {
            if (defender.GetValue(BTL_POKEPARAM.ValueID.BPP_HP) > damage)
                return KoraeruCause.NONE;

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, defender.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.GEN_FLAG, isWazaDamage ? TRUE : FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.KORAERU_CAUSE, (int)KoraeruCause.NONE);
            m_pEventSystem.CallEvent(EventID.KORAERU_CHECK);
            KoraeruCause cause = (KoraeruCause)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.KORAERU_CAUSE);
            m_pEventSystem.EVENTVAR_Pop();

            if (cause == KoraeruCause.NONE)
            {
                byte friendship = SectionUtil.GetFriendship(m_pMainModule, defender);
                uint per;
                if (friendship == 255)
                    per = 20;
                else if (friendship >= 220)
                    per = 15;
                else if (friendship >= 180)
                    per = 10;
                else
                    per = 0;

                if (!calc.IsOccurPer(per))
                    return KoraeruCause.NONE;

                cause = KoraeruCause.FRIENDSHIP;
            }

            damage = (ushort)(defender.GetValue(BTL_POKEPARAM.ValueID.BPP_HP) - 1);
            return cause;
        }
