		public global::Pml.WazaData.WazaSick Event_CheckWazaAddSick(global::Pml.WazaNo waza, global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.BTL_POKEPARAM defender, out global::Dpr.Battle.Logic.BTL_SICKCONT pSickCont) {
            pSickCont = SICKCONT.MakeNull();

            BTL_SICKCONTOBJ sickCont = new BTL_SICKCONTOBJ();
            WazaSick sick = WAZADATA.GetSick(waza);
            SickContParam wazaSickCont = WAZADATA.GetSickCont(waza);
            int per = WAZADATA.GetSickPer(waza);
            calc.WazaSickContToBppSickCont(wazaSickCont, attacker, out sickCont.value);

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, defender.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZAID, (int)waza);
            m_pEventSystem.EVENTVAR_SetWorkAddress(EventVar.Label.SICK_CONT_ADRS, sickCont);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.SICKID, (int)sick);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FAIL_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.ADD_PER, per);
            m_pEventSystem.CallEvent(EventID.ADD_SICK);
            sick = (WazaSick)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.SICKID);
            per = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.ADD_PER);
            int failFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FAIL_FLAG);
            if (sick == WazaSick.WAZASICK_SPECIAL_CODE)
                sick = WazaSick.WAZASICK_NONE;
            m_pEventSystem.EVENTVAR_Pop();

            if (sick != WazaSick.WAZASICK_NONE && failFlag == FALSE && per > 0 && perOccur((byte)per, out _))
            {
                pSickCont = sickCont.value;
                return sick;
            }

            return WazaSick.WAZASICK_NONE;
        }
