            byte defPokeID = defender.GetID();

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, defPokeID);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.ORG_WAZAID, (int)wazaParam.orgWazaID);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZAID, (int)wazaParam.wazaID);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.TYPEAFF, (int)aff);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZA_TYPE, wazaParam.wazaType);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.DAMAGE_TYPE, (int)wazaParam.damageType);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.DAMAGE, (int)damage);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.CRITICAL_FLAG, fCritical ? TRUE : FALSE);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.MIGAWARI_FLAG, fMigawari ? TRUE : FALSE);
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZA_TOUCH_FLAG, wazaParam.touchFlag ? TRUE : FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.RINPUNGUARD_FLG, FALSE);
            m_pEventSystem.CallEvent(EventID.WAZA_DMG_REACTION_PREV);
            m_pEventSystem.CallEvent(EventID.WAZA_DMG_REACTION);
            m_pEventSystem.CallEvent(EventID.WAZA_DMG_REACTION_L2);
