		public bool Event_UnCategoryWaza(global::Dpr.Battle.Logic.WazaParam wazaParam, global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.PokeSet targets, out bool fFailMsgEnable) {
            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());

            byte targetCount = (byte)targets.GetCount();
            byte targetCountMax = (byte)targets.GetCountMax();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.TARGET_POKECNT, targetCount);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.GEN_FLAG, TRUE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.NOEFFECT_FLAG, TRUE);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.SUCCESS_FLAG, FALSE);
            for (byte i = 0; i < targetCount; i++)
                m_pEventSystem.EVENTVAR_SetConstValue(LABEL_OFFSET(EventVar.Label.POKEID_TARGET1, i), targets.Get(i).GetID());

            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.WAZAID, (int)wazaParam.wazaID);

            EventID eventID = targetCountMax != 0 ? EventID.UNCATEGORIZE_WAZA : EventID.UNCATEGORIZE_WAZA_NO_TARGET;
            m_pEventSystem.CallEvent(eventID);
            fFailMsgEnable = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GEN_FLAG) != FALSE;
            int successFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.SUCCESS_FLAG);
            m_pEventSystem.EVENTVAR_Pop();

            return successFlag != FALSE;
        }
