		public bool Event_TameStart(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.PokeSet targetRec, global::Dpr.Battle.Logic.WazaParam wazaParam, ref byte hideTargetPokeID, ref bool fFailMsgDisped) {
            byte targetCount = (byte)targetRec.GetCount();

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.TARGET_POKECNT, targetCount);
            if (targetCount == 0)
            {
                m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_TARGET1, PokeID.INVALID);
            }
            else
            {
                for (uint i = 0; i < targetCount; i++)
                    m_pEventSystem.EVENTVAR_SetConstValue(LABEL_OFFSET(EventVar.Label.POKEID_TARGET1, i), targetRec.Get(i).GetID());
            }

            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.FAIL_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.GEN_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetRewriteOnceValue(EventVar.Label.MSG_FLAG, FALSE);
            m_pEventSystem.EVENTVAR_SetWorkAddress(EventVar.Label.WORK_ADRS, wazaParam);
            m_pEventSystem.CallEvent(EventID.TAME_START);

            if (m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.GEN_FLAG) != FALSE)
                hideTargetPokeID = (byte)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.POKEID_TARGET1);
            else
                hideTargetPokeID = PokeID.INVALID;

            fFailMsgDisped = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.MSG_FLAG) != FALSE;
            int failFlag = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.FAIL_FLAG);
            m_pEventSystem.EVENTVAR_Pop();

            return failFlag == FALSE;
        }
