		public ushort Event_RecalcDrainVolume(global::Dpr.Battle.Logic.BTL_POKEPARAM attacker, global::Dpr.Battle.Logic.BTL_POKEPARAM target, ushort volume) {
            byte targetPokeID = target != null ? target.GetID() : PokeID.INVALID;

            m_pEventSystem.EVENTVAR_Push();
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_ATK, attacker.GetID());
            m_pEventSystem.EVENTVAR_SetConstValue(EventVar.Label.POKEID_DEF, targetPokeID);
            m_pEventSystem.EVENTVAR_SetMulValue(EventVar.Label.RATIO, 0x1000, 0x19a, 0x20000);
            m_pEventSystem.EVENTVAR_SetValue(EventVar.Label.VOLUME, volume);
            m_pEventSystem.CallEvent(EventID.CALC_DRAIN);
            volume = (ushort)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.VOLUME);
            int ratio = m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.RATIO);
            if (volume != 0)
                volume = (ushort)calc.MulRatio_OverZero(volume, ratio);

            m_pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.VOLUME, volume);
            m_pEventSystem.CallEvent(EventID.CALC_DRAIN_END);
            volume = (ushort)m_pEventSystem.EVENTVAR_GetValue(EventVar.Label.VOLUME);
            m_pEventSystem.EVENTVAR_Pop();

            return volume;
        }
